VERSION = "fd 10.3.0"

def get_bin_name():
    return os.path.basename(sys.argv[0]) if sys.argv else "executable"

def load_help(short=False):
    # Try to load help files relative to script location
    try:
        script_dir = os.path.dirname(os.path.abspath(__file__))
    except:
        script_dir = os.path.dirname(os.path.abspath(sys.argv[0])) if sys.argv else "."
    fname = "help_short.txt" if short else "help_long.txt"
    # Try script dir, then cwd, then workspace
    for d in [script_dir, ".", "/workspace"]:
        p = os.path.join(d, fname)
        if os.path.exists(p):
            with open(p, "r", encoding="utf-8") as f:
                content = f.read()
            # Replace binary name in Usage line
            bin_name = get_bin_name()
            if bin_name != "executable":
                content = content.replace("Usage: executable", f"Usage: {bin_name}")
            return content
    return ""

def print_help(short=False):
